use crate::*;use std::time::Duration;
pub fn split(text:&str,budget:usize)->Result<Vec<String>>{if budget<4{return Err("分段预算太小".into())}let mut p=vec![];let mut s=String::new();for c in text.chars(){if s.len()+c.len_utf8()>budget{p.push(std::mem::take(&mut s));}s.push(c)}if !s.is_empty()||p.is_empty(){p.push(s)}Ok(p)}
pub fn prepare_parts(m:&Message,kind:ChannelKind,computer:&str)->Result<Vec<String>>{let state=match m.state{AgentState::Unknown=>"通知",AgentState::TurnEnded=>"一轮回复结束",AgentState::ProcessExited=>"进程退出",AgentState::Succeeded=>"任务成功",AgentState::Failed=>"任务失败",AgentState::WaitingInput=>"等待输入"};let mut text=format!("[{state}] {}\n{}\n{}\n电脑：{}\n时间：{}",m.app_name,m.title,m.body,computer,m.occurred_at.with_timezone(&chrono::Local).format("%Y-%m-%d %H:%M:%S"));if !m.project.is_empty(){text.push_str(&format!("\n项目：{}",m.project))}if text.len()>65536{let suffix="\n[正文过长，已截断]";let mut n=65536-suffix.len();while !text.is_char_boundary(n){n-=1}text.truncate(n);text.push_str(suffix)}let budget=if kind==ChannelKind::WeCom{1800}else{15000};if text.len()<=budget{return Ok(vec![text])}let chunks=split(&text,budget-32)?;let total=chunks.len();Ok(chunks.into_iter().enumerate().map(|(i,s)|format!("[{}/{total}]\n{s}",i+1)).collect())}
pub fn next_delay(n:u32,server:Option<Duration>)->Option<Duration>{[30,120,600,1800,7200].get(n as usize).map(|s|Duration::from_secs(*s).max(server.unwrap_or_default()))}
